function validate([key, message]) {
  if (typeof key !== 'string' || key.length < 26 || key.length > 2000) return 'key needs 26 to 2000 characters.';
  if (!/^[a-z ]+$/.test(key)) return 'key may contain only lowercase letters and spaces.';
  if (new Set(key.replace(/ /g, '')).size !== 26) return 'key must contain every letter from a to z.';
  if (typeof message !== 'string' || message.length < 1 || message.length > 2000) return 'message needs 1 to 2000 characters.';
  if (!/^[a-z ]+$/.test(message)) return 'message may contain only lowercase letters and spaces.';
  return null;
}

