  for (const ch of key) {
    if (ch !== ' ' && !table.has(ch)) {
      table.set(ch, String.fromCharCode(97 + next));
      next++;
    }
  }
  const decoded = [];
  for (const ch of message) {
    decoded.push(ch === ' ' ? ' ' : table.get(ch));
  }
