function decodeMessage(key, message) {
  // The de-duplicated letters of key, in order; a letter's index there is its alphabet position.
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const order = [...new Set(key.split(' ').join(''))];
  let out = '';
  for (const ch of message) out += ch === ' ' ? ' ' : alphabet[order.indexOf(ch)];
  return out;
}

