function generate(rand, size) {
  const symbols = 'abcdefghijklmnopqrstuvwxyz ';
  const pick = () => symbols[Math.floor(rand() * symbols.length)];
  const keyLength = size === 'large' ? 2000 : 26 + Math.floor(rand() * 15);
  // Random filler, then every letter (in a shuffled order) inserted at a random place, so all 26 appear.
  const key = Array.from({ length: keyLength - 26 }, pick);
  const letters = symbols.slice(0, 26).split('');
  for (let i = letters.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [letters[i], letters[j]] = [letters[j], letters[i]];
  }
  for (const letter of letters) key.splice(Math.floor(rand() * (key.length + 1)), 0, letter);
  const messageLength = size === 'large' ? 2000 : 1 + Math.floor(rand() * 15);
  const message = Array.from({ length: messageLength }, pick).join('');
  return [key.join(''), message];
}
